/**
 * 사이퍼(캐릭터) 프로필 — 능력치·스킬.
 * Neople 오픈 API 는 이 데이터를 제공하지 않으므로 공식 사이트(cyphers.nexon.com)
 * 기준 정적 데이터로 관리한다. key = characterName(한글).
 * 데이터가 있는 캐릭터만 상세 페이지에 능력치·스킬 UI 가 렌더된다.
 */

export interface CypherStat {
  attack: number; // 공격
  vitality: number; // 체력
  evasion: number; // 회피
  critical: number; // 치명
  defense: number; // 방어
  movement: number; // 이동
}

export interface CypherSkillInfo {
  slot: string; // LMB / RMB / Q / E / F / Space / Shift+LMB / Wheel Up / Passive ...
  name: string;
  cooldown?: string; // "16.50초"
  cost?: string;
  explain: string;
}

export interface CypherProfile {
  slug: string; // cyphers.nexon.com 영문 슬러그
  attackType?: string; // 원거리 / 근거리
  difficulty?: number; // 1~5 (★ 개수)
  roleDesc?: string; // 한 줄 소개
  stat?: CypherStat;
  skills?: CypherSkillInfo[];
}

/** 능력치 표시 설정 — 라벨 + 바 정규화용 대략 최대값 + 색 */
export const STAT_DISPLAY: { key: keyof CypherStat; label: string; max: number; color: string }[] = [
  { key: "attack", label: "공격", max: 130, color: "#e2506a" },
  { key: "vitality", label: "체력", max: 2100, color: "#4fbf6b" },
  { key: "defense", label: "방어", max: 35, color: "#5b8def" },
  { key: "critical", label: "치명", max: 110, color: "#e3b23c" },
  { key: "evasion", label: "회피", max: 110, color: "#a15bf0" },
  { key: "movement", label: "이동", max: 345, color: "#4f8ff0" },
];

